package integration_test
import("context";"testing";"time";"github.com/vance1852/foodsafe-traceability/internal/domain";"github.com/vance1852/foodsafe-traceability/internal/permit")
func TestPermitActivationRollsBackWhenAuditFails(t *testing.T){f:=newFixture(t);g:=f.createSourceGraph(t);now:=time.Now().UTC();p,err:=f.permits.Create(context.Background(),f.supervisor,permit.CreateCommand{FacilityID:g.source.ID,HolderName:"Plant",Reference:"PRIVATE-ACT",ValidFrom:now.Add(-time.Hour),ValidUntil:now.Add(time.Hour),DailyVolumeLimitLiters:1000,RequestID:"private-permit-create"});if err!=nil{t.Fatal(err)};if _,err=f.store.DB().Exec(`CREATE TRIGGER fail_permit_activation_audit BEFORE INSERT ON audit_events WHEN NEW.action = 'permit.activate' BEGIN SELECT RAISE(ABORT, 'audit sink unavailable'); END`);err!=nil{t.Fatal(err)};if err=f.permits.Activate(context.Background(),f.supervisor,p.ID,"private-permit-failing");err==nil{t.Fatal("activation unexpectedly succeeded")};var status string;if err=f.store.DB().QueryRow(`SELECT status FROM permits WHERE id=?`,p.ID).Scan(&status);err!=nil{t.Fatal(err)};if status!=string(domain.PermitDraft){t.Fatalf("failed activation left status %q",status)};if _,err=f.store.DB().Exec(`DROP TRIGGER fail_permit_activation_audit`);err!=nil{t.Fatal(err)};if err=f.permits.Activate(context.Background(),f.supervisor,p.ID,"private-permit-retry");err!=nil{t.Fatal(err)};if err=f.store.DB().QueryRow(`SELECT status FROM permits WHERE id=?`,p.ID).Scan(&status);err!=nil{t.Fatal(err)};if status!=string(domain.PermitActive){t.Fatalf("retry status %q",status)}}
